public UnitState inbetweenStatesAt(UnitState state1, UnitState state2, float t) {
    UPoint uPointCopy;
    float fInterpolateScalar = interpolateScalar(state1.getBase().x, state2.getBase().x, t);
    float fInterpolateScalar2 = interpolateScalar(state1.getBase().y, state2.getBase().y, t);
    float fInterpolateScalar3 = interpolateScalar(state1.mScale, state2.mScale, t);
    float fInterpolateScalar4 = interpolateScalar(state1.mAlpha, state2.mAlpha, t);
    UnitState unitState = new UnitState();
    char c = 0;
    unitState.set(state1, false);
    UnmodifiableIterator it = FluentIterable.from(state1.mEdges).toSortedList(new UEdge.ProximityComparator()).iterator();
    while (it.hasNext()) {
        UEdge uEdge = (UEdge) it.next();
        UEdge uEdgeFindEdgeByPointsId = state2.findEdgeByPointsId(uEdge.mStart.getId(), uEdge.mEnd.getId());
        boolean zIsBase = uEdge.mStart.isBase();
        UPoint uPointCopy2 = uEdge.mEnd.copy();
        if (zIsBase) {
            uPointCopy = uEdge.mStart.copy();
        } else {
            uPointCopy = unitState.findPointById(uEdge.mStart.getId()).copy();
        }
        float fInterpolateEdgeLength = interpolateEdgeLength(uEdge, state1, uEdgeFindEdgeByPointsId, state2, t);
        float[] fArrInterpolateDirection = interpolateDirection(uEdge, uEdgeFindEdgeByPointsId, t);
        char c2 = c;
        uPointCopy2.x = uPointCopy.x + (fArrInterpolateDirection[c2] * fInterpolateEdgeLength);
        uPointCopy2.y = uPointCopy.y + (fArrInterpolateDirection[1] * fInterpolateEdgeLength);
        if (uEdge.mStart.isBase()) {
            float f = fInterpolateScalar - state1.getBase().x;
            float f2 = fInterpolateScalar2 - state1.getBase().y;
            uPointCopy.x += f;
            uPointCopy.y += f2;
            uPointCopy2.x += f;
            uPointCopy2.y += f2;
            if (!unitState.tryGetBase().isPresent()) {
                unitState.insertPoint(uPointCopy);
            }
        }
        uPointCopy2.mParentId = uPointCopy.getId();
        unitState.insertPoint(uPointCopy2);
        c = c2;
    }
    if (state1.mFlipped != state2.mFlipped) {
        unitState.mFlipped = t < 0.5f ? state1.mFlipped : state2.mFlipped;
    }
    unitState.scaleAt(unitState.getBase().x, unitState.getBase().y, fInterpolateScalar3);
    unitState.mAlpha = Math.max(0.0f, Math.min(1.0f, fInterpolateScalar4));
    return unitState;
}
